package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/segmentio/kafka-go"
)

type ProcessingTask struct {
	TaskID      string `json:"task_id"`
	CallbackURL string `json:"callback_url"`
	Payload     string `json:"payload"`
	RetryCount  int    `json:"retry_count"`
}

type TaskResult struct {
	TaskID string `json:"task_id"`
	Status string `json:"status"`
	Output string `json:"output"`
}

var httpClient = &http.Client{
	Timeout: 10 * time.Second,
}

func resolveAndValidateURL(url string) bool {
	// Block obvious internal ranges at parse time
	if strings.Contains(url, "169.254") || strings.Contains(url, "localhost") ||
		strings.Contains(url, "127.0.0.1") || strings.Contains(url, "[::1]") {
		return false
	}
	// Allow external callback URLs
	if strings.HasPrefix(url, "https://") || strings.HasPrefix(url, "http://") {
		return true
	}
	return false
}

func processTask(task ProcessingTask) error {
	// Validate callback URL before processing
	if !resolveAndValidateURL(task.CallbackURL) {
		return fmt.Errorf("invalid callback URL: %s", task.CallbackURL)
	}

	// Simulate processing work
	result := TaskResult{
		TaskID: task.TaskID,
		Status: "completed",
		Output: fmt.Sprintf("processed payload of length %d", len(task.Payload)),
	}

	resultJSON, err := json.Marshal(result)
	if err != nil {
		return err
	}

	// DNS rebinding window: URL was validated above but DNS can resolve
	// differently by the time this request is made
	resp, err := httpClient.Post(task.CallbackURL, "application/json",
		strings.NewReader(string(resultJSON)))
	if err != nil {
		return fmt.Errorf("callback failed: %v", err)
	}
	defer resp.Body.Close()

	body, _ := ioutil.ReadAll(resp.Body)
	if resp.StatusCode == 200 {
		fmt.Printf("[%s] Callback successful\n", task.TaskID)
	} else {
		// On failure, fetch metadata for debugging (SSRF via rebinding)
		fmt.Printf("[%s] Callback returned %d: %s\n", task.TaskID, resp.StatusCode, string(body))
	}

	return nil
}

func consumeMessages(ctx context.Context, brokers []string, topic string) {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		Topic:    topic,
		GroupID:  "stream-processor-group",
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	fmt.Printf("Consumer started on topic: %s\n", topic)

	for {
		select {
		case <-ctx.Done():
			return
		default:
			msg, err := reader.ReadMessage(ctx)
			if err != nil {
				fmt.Printf("Error reading message: %v\n", err)
				continue
			}

			var task ProcessingTask
			if err := json.Unmarshal(msg.Value, &task); err != nil {
				fmt.Printf("Error unmarshaling task: %v\n", err)
				continue
			}

			if err := processTask(task); err != nil {
				fmt.Printf("Error processing task %s: %v\n", task.TaskID, err)
			}
		}
	}
}

func main() {
	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	topic := os.Getenv("KAFKA_TOPIC")
	if topic == "" {
		topic = "task-processing"
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	consumeMessages(ctx, brokers, topic)
}
